        "testata": "Limes",
        "lingua_originale": "it",
        "titolo_orig": "Parabola dello schianto imperiale americano",
        "testo_it": "Analisi: crisi d'identità e declino dell'egemonia globale degli Stati Uniti nel contesto geopolitico attuale.",
        "priorita": "Alta",
